sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?school ?country WHERE {
  VALUES ?school { dbr:Russell_High_School_(Ontario) dbr:Westside_Christian_High_School }

  # Try direct country property (prefer dbp: as per rule)
  OPTIONAL { ?school dbp:country ?country . }

  # Fallback: get country via the city entity
  OPTIONAL {
    ?school dbo:city ?city .
    ?city dbo:country ?country .
  }
}
LIMIT 100

